//! Issuance boundary tests for executor catalog packed admission.
//! Verifies counter length boundaries, u64::MAX overflow, and
//! overflow-then-retry behavior through the packed submission path.

use super::issuance_test_support::*;
use crate::JournalError;
use crate::executor::ExecutorError;
use vb_core::RuntimePolicy;

/// Counter stored as 7 bytes yields EXACT
/// ExecutorError::Artifact(JournalError::MalformedKeyspaceRow{prefix:0,
/// expected_len:8, actual_len:7}). Raw counter bytes unchanged and compiled_ir
/// empty before any submission.
#[test]
fn malformed_counter_seven_bytes() -> TestResult {
    let fixture = PackedFixture::new()?;
    let (_dir, journal) = open_test_journal()?;

    let short = vec![0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77];
    journal.artifact_acceptance.insert(b"last_issued", &short)?;

    let result = fixture.submit(&journal, RuntimePolicy::Relaxed);
    let got = matches!(
        &result,
        Err(ExecutorError::Artifact(JournalError::MalformedKeyspaceRow {
            prefix,
            expected_len,
            actual_len
        })) if *prefix == 0 && *expected_len == 8 && *actual_len == 7
    );
    if !got {
        return Err(format!("expected MalformedKeyspaceRow(actual_len=7), got: {result:?}").into());
    }

    let stored = journal
        .artifact_acceptance
        .get(b"last_issued")?
        .ok_or("counter row should still exist")?;
    if stored.as_ref() != short.as_slice() {
        return Err("counter row bytes changed".into());
    }
    if journal.compiled_ir.iter().next().is_some() {
        return Err("compiled_ir should be empty".into());
    }
    Ok(())
}

/// Counter stored as 9 bytes yields EXACT MalformedKeyspaceRow with
/// actual_len=9.
#[test]
fn malformed_counter_nine_bytes() -> TestResult {
    let fixture = PackedFixture::new()?;
    let (_dir, journal) = open_test_journal()?;

    let long = vec![0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99];
    journal.artifact_acceptance.insert(b"last_issued", &long)?;

    let result = fixture.submit(&journal, RuntimePolicy::Relaxed);
    let got = matches!(
        &result,
        Err(ExecutorError::Artifact(JournalError::MalformedKeyspaceRow {
            prefix,
            expected_len,
            actual_len
        })) if *prefix == 0 && *expected_len == 8 && *actual_len == 9
    );
    if !got {
        return Err(format!("expected MalformedKeyspaceRow(actual_len=9), got: {result:?}").into());
    }

    let stored = journal
        .artifact_acceptance
        .get(b"last_issued")?
        .ok_or("counter row should still exist")?;
    if stored.as_ref() != long.as_slice() {
        return Err("counter row bytes changed".into());
    }
    if journal.compiled_ir.iter().next().is_some() {
        return Err("compiled_ir should be empty".into());
    }
    Ok(())
}

/// Counter at u64::MAX yields EXACT
/// ExecutorError::Artifact(JournalError::ArtifactSequenceOverflow). Counter
/// remains at u64::MAX and compiled_ir is empty.
#[test]
fn counter_at_max_yields_sequence_overflow() -> TestResult {
    let fixture = PackedFixture::new()?;
    let (_dir, journal) = open_test_journal()?;

    write_counter(&journal, u64::MAX)?;

    let result = fixture.submit(&journal, RuntimePolicy::Relaxed);
    let got = matches!(
        &result,
        Err(ExecutorError::Artifact(JournalError::ArtifactSequenceOverflow))
    );
    if !got {
        return Err(format!("expected SequenceOverflow at u64::MAX, got: {result:?}").into());
    }

    let counter = read_counter(&journal)?;
    if counter != Some(u64::MAX) {
        return Err("counter should remain at u64::MAX".into());
    }
    if journal.compiled_ir.iter().next().is_some() {
        return Err("compiled_ir should be empty at overflow".into());
    }
    Ok(())
}

/// Counter at u64::MAX-1 allows one more submission at u64::MAX.
/// Subsequent submission fails with EXACT ArtifactSequenceOverflow; counter
/// stays at u64::MAX and the prior artifact remains fully readable.
#[test]
fn counter_at_max_minus_one_allows_one_more() -> TestResult {
    let fixture = PackedFixture::new()?;
    let (_dir, journal) = open_test_journal()?;

    write_counter(&journal, u64::MAX.checked_sub(1).ok_or("max predecessor")?)?;

    let artifact = fixture.submit(&journal, RuntimePolicy::Relaxed)?;
    if artifact.accepted_at_seq.get() != u64::MAX {
        return Err("submission should yield seq u64::MAX".into());
    }
    fixture.check(&journal, &artifact, RuntimePolicy::Relaxed)?;

    let counter = read_counter(&journal)?;
    if counter != Some(u64::MAX) {
        return Err("counter should be u64::MAX after submission".into());
    }

    let result = fixture.submit(&journal, RuntimePolicy::Relaxed);
    let got = matches!(
        &result,
        Err(ExecutorError::Artifact(JournalError::ArtifactSequenceOverflow))
    );
    if !got {
        return Err(format!("expected SequenceOverflow after u64::MAX, got: {result:?}").into());
    }

    let counter_after = read_counter(&journal)?;
    if counter_after != Some(u64::MAX) {
        return Err("counter should remain at u64::MAX after overflow".into());
    }
    fixture.check(&journal, &artifact, RuntimePolicy::Relaxed)?;
    Ok(())
}

