    assert_eq!(default_artifact.accepted_at_seq.get(), 1);
    let catalog_artifact = fixture.submit(&journal, RuntimePolicy::Relaxed)?;
    assert_eq!(catalog_artifact.accepted_at_seq.get(), 2);
