        let (_dir, journal) = open_test_journal()?;
        assert_eq!(read_counter(&journal)?, None);
        assert!(journal.list_artifacts()?.is_empty());
        let artifact = fixture.prepare(*policy)?;
        assert_eq!(artifact.accepted_at_seq.get(), 0);
        assert_eq!(read_counter(&journal)?, None);
        assert!(journal.list_artifacts()?.is_empty());
    }
    Ok(())
}

