    fixture.check(&journal, &journaled, RuntimePolicy::Journaled)?;
    fixture.check(&journal, &relaxed, RuntimePolicy::Relaxed)?;
    assert_eq!(read_counter(&journal)?, Some(3));
    Ok(())
}

